     8→/**
     9→ * If a user arrive to `/orgs` we redirect them to the first organization they are part of.
    10→ *
    11→ * 💡 If you want to redirect user to organization page, redirect them to `/orgs`
    12→ * 💡 If you want them to redirect to a specific organization, redirect them to `/orgs/orgSlug`
    13→ */
    14→export const GET = async () => {
    15→  const user = await getUser();
    16→
    17→  if (!user) {
    18→    return NextResponse.redirect(`${getServerUrl()}/auth/signin`);
    19→  }
    20→
    21→  const member = await prisma.member.findFirst({
    22→    where: {
    23→      userId: user.id,
    24→    },
    25→    select: {
    26→      organization: {
    27→        select: {
    28→          slug: true,
    29→          id: true,
    30→        },
    31→      },
    32→    },
    33→  });
    34→
    35→  if (!member?.organization.id) {
    36→    return NextResponse.redirect(`${getServerUrl()}/orgs/new`);
    37→  }
    38→
    39→  // Set The active organization in the session
    40→  await auth.api.setActiveOrganization({
    41→    body: {
    42→      organizationId: member.organization.id,
    43→    },
    44→    headers: await headers(),
    45→  });
    46→
    47→  return NextResponse.redirect(
    48→    `${getServerUrl()}/orgs/${member.organization.slug}`,
    49→  );
    50→};
