     1→import { prisma } from "@/lib/prisma";
     2→import { stripe } from "@/lib/stripe";
     3→import { getPlanLimits } from "../auth/stripe/auth-plans";
     4→import { logger } from "../logger";
     5→
     6→export const getOrgActiveSubscription = async (organizationId: string) => {
     7→  // Get subscription from database
     8→  const subscription = await prisma.subscription.findFirst({
     9→    where: {
    10→      referenceId: organizationId,
    11→      OR: [
    12→        { status: "active" },
    13→        { status: "trialing" },
    14→        { status: "past_due" }, // Include past_due as it's still technically active
    15→      ],
    16→    },
    17→  });
    18→
    19→  if (!subscription?.stripeSubscriptionId) {
    20→    return null;
    21→  }
    22→
    23→  try {
    24→    // Verify subscription status with Stripe
    25→    const stripeSubscription = await stripe.subscriptions.retrieve(
    26→      subscription.stripeSubscriptionId,
    27→    );
    28→
    29→    // If Stripe says it's not active, update our database
    30→    if (
    31→      !["active", "trialing", "past_due"].includes(stripeSubscription.status)
    32→    ) {
    33→      await prisma.subscription.update({
    34→        where: { id: subscription.id },
    35→        data: {
    36→          status: stripeSubscription.status,
    37→          // If canceled, revert to free plan
    38→          ...(stripeSubscription.status === "canceled" && { plan: "free" }),
    39→        },
    40→      });
    41→      return null;
    42→    }
    43→
    44→    // Return subscription with updated Stripe data
    45→    return {
    46→      ...subscription,
    47→      status: stripeSubscription.status,
    48→      cancelAtPeriodEnd: stripeSubscription.cancel_at_period_end,
    49→      limits: getPlanLimits(subscription.plan),
    50→    };
    51→  } catch (error) {
    52→    logger.error("Error fetching Stripe subscription:", error);
    53→    // If Stripe fails, return database subscription
    54→    return {
    55→      ...subscription,
    56→      status: subscription.status,
    57→      cancelAtPeriodEnd: null,
    58→      limits: getPlanLimits(subscription.plan),
    59→    };
    60→  }
    61→};
