     1→import type { AuthRole } from "../auth/auth-permissions";
     2→
     3→/**
     4→ *
     5→ * @param userRoles User's roles
     6→ * @param rolesNeeded Roles to check
     7→ * @returns a boolean indicating if the user has at least one role in rolesB
     8→ */
     9→export const isInRoles = (userRoles?: AuthRole[], rolesNeeded?: AuthRole[]) => {
    10→  if (!userRoles) return false;
    11→
    12→  // Owner can access to everything
    13→  if (userRoles.includes("owner")) return true;
    14→
    15→  if (!rolesNeeded) return true;
    16→  return rolesNeeded.every((role) => userRoles.includes(role));
    17→};
