     9→    const session = await auth.api.getSession({
    10→      headers: await headers(),
    11→    });
    12→    if (!session?.user) {
    13→      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    14→    }
    15→
    16→    const { action, favoriteId, userId } = await request.json();
    17→
    18→    const enrichmentService = new FavoriteEnrichmentService();
    19→
    20→    switch (action) {
    21→      case "enrich-favorite": {
    22→        if (!favoriteId) {
    23→          return NextResponse.json(
    24→            { error: "favoriteId is required" },
    25→            { status: 400 },
    26→          );
    27→        }
    28→
    29→        // Vérifier que le favori appartient à l'utilisateur
    30→        const { PrismaClient } = await import("@/generated/prisma");
    31→        const prisma = new PrismaClient();
    32→        const favorite = await prisma.favorite.findFirst({
    33→          where: {
    34→            id: favoriteId,
    35→            userId: session.user.id,
    36→          },
    37→        });
    38→
    39→        if (!favorite) {
    40→          return NextResponse.json(
    41→            { error: "Favorite not found or access denied" },
    42→            { status: 404 },
    43→          );
    44→        }
    45→
    46→        const result =
    47→          await enrichmentService.enrichFavoriteWithDPE(favoriteId);
    48→        return NextResponse.json(result);
    49→      }
    50→
    51→      case "enrich-user-favorites": {
    52→        const targetUserId = userId ?? session.user.id;
    53→
    54→        // Vérifier les permissions
    55→        if (targetUserId !== session.user.id && session.user.role !== "admin") {
    56→          return NextResponse.json(
    57→            { error: "Unauthorized to enrich other user's favorites" },
    58→            { status: 403 },
    59→          );
    60→        }
    61→
    62→        const userResults =
    63→          await enrichmentService.enrichUserFavorites(targetUserId);
    64→        return NextResponse.json({
    65→          success: true,
    66→          results: userResults,
    67→          total: userResults.length,
    68→          successful: userResults.filter((r) => r.success).length,
    69→          failed: userResults.filter((r) => !r.success).length,
    70→        });
    71→      }
    72→
    73→      case "enrich-all-without-dpe": {
    74→        // Admin seulement
    75→        if (session.user.role !== "admin") {
    76→          return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
    77→        }
    78→
    79→        const allResults =
