    86→          failed: allResults.filter((r) => !r.success).length,
    87→        });
    88→      }
    89→
    90→      default:
    91→        return NextResponse.json({ error: "Invalid action" }, { status: 400 });
    92→    }
    93→  } catch (error) {
    94→    console.debug("Error in DPE enrichment API:", error);
