    23→const searchParamsCache = createSearchParamsCache({
    24→  search: parseAsString.withDefault(DEFAULT_FILTERS.search),
    25→  type: parseAsString.withDefault(DEFAULT_FILTERS.type),
    26→  category: parseAsString.withDefault(DEFAULT_FILTERS.category),
    27→  priceMin: parseAsString.withDefault(DEFAULT_FILTERS.priceMin),
